/*
 * Scilab grammar for highlight.js 11 (help browser).
 *
 * Derived from the stock highlight.js "scilab" language. The keyword lists
 * below are a fallback for standalone pages: in the help browser,
 * scilab-init.js appends the lists of getscilabkeywords() (commands,
 * predefined variables, primitives, macros) before the first highlight.
 *
 * classdef: properties / methods / enumeration are keywords only inside a
 * classdef body (like the structure keywords of SciNotes); elsewhere they
 * are the functions of the same name (enumeration(e), methods(obj)). The
 * classdef body is parsed as nested blocks so that every "end" closes the
 * right construct.
 */
(function () {
    function scilab(hljs) {
        // Shared by every mode: scilab-init.js enriches this object (through
        // hljs.getLanguage("scilab").keywords) before the first highlight
        var KEYWORDS = {
            $pattern: /%?\w+/,
            // Syntax keywords, kept even when getscilabkeywords() lists some
            // of them as primitives (see scilab-init.js)
            keyword: "abort break case clear catch continue do elseif else endfunction end exit for function global if otherwise pause quit return resume select switch try then while",
            literal: "%f %F %t %T %pi %eps %inf %nan %e %i %z %s",
            built_in: "abs and acos asin atan ceil cd chdir clearglobal cosh cos cumprod deff disp error exec execstr exists exp eye gettext floor fprintf fread fsolve imag isdef isempty isinfisnan isvector lasterror length load linspace list listfiles log10 log2 log max min msprintf mclose mopen ones or pathconvert poly printf prod pwd rand real round sinh sin size gsort sprintf sqrt strcat strcmps tring sum system tanh tan type typename warning zeros matrix"
        };

        // A quote right after an operand (name, number, ")", "]", "}", ".",
        // transpose or string) is a transpose, not a string: f(x)', a.', x''.
        // Scilab has no backslash escape: quotes are escaped by doubling.
        var STRING = {
            className: "string",
            begin: /"|(?<![\w)\]}.'"])'/,
            end: "'|\"",
            contains: [{begin: /''|""/}]
        };
        var COMMENT = hljs.COMMENT("//", "$");
        // Field access and transpose: not keywords (a.end, x')
        var FIELD = {begin: "[a-zA-Z_][a-zA-Z_0-9]*[\\.']+", relevance: 0};
        // Matrix literal: same keywords as outside (%nan, sin...), nested
        // matrices, transposes and comments of multi-line matrices
        var MATRIX = {begin: "\\[", end: "\\][\\.']*", relevance: 0, keywords: KEYWORDS, contains: []};
        MATRIX.contains = [hljs.C_NUMBER_MODE, STRING, FIELD, "self", COMMENT];
        var BASE = [hljs.C_NUMBER_MODE, STRING, FIELD, MATRIX, COMMENT];

        // "function [outputs] = name(inputs)" header. Every output and input
        // name is a "params" token (InputOutputArgs, also colored in the
        // function body by scilab-init.js), the function name a "title".
        // Stops before an end/endfunction on the same line (one-line
        // function: "function f(), end"), which is then closed by the
        // enclosing context.
        var ARG = {className: "params", begin: /[a-zA-Z_%#!$?][\w#!$?]*/, relevance: 0};
        var FUNCTION_HEADER = {
            className: "function",
            beginKeywords: "function",
            end: /$|\b(end|endfunction)\b/,
            returnEnd: true,
            contains: [
                // outputs: "[a, b] =" or "a ="
                {begin: /\[/, end: /\]/, contains: [ARG]},
                {className: "params", begin: /[a-zA-Z_%#!$?][\w#!$?]*(?=\s*=)/, relevance: 0},
                // function name (never the closing keyword)
                {className: "title", begin: /(?<![\w#!$?])(?!(end|endfunction)\b)[a-zA-Z_%#!$?][\w#!$?]*/, relevance: 0},
                // the header ends with the input list
                {begin: /\(/, end: /\)/, endsParent: true, contains: [ARG]},
                COMMENT
            ]
        };

        // ---- classdef body: nested blocks ---------------------------------

        // if/for/while/select/try/arguments ... end
        var BLOCK = {
            begin: /\b(if|for|while|select|switch|try|arguments)\b/,
            beginScope: "keyword",
            end: /\bend\b/,
            endScope: "keyword",
            keywords: KEYWORDS,
            contains: []
        };
        // function header, then body up to end/endfunction
        var FUNCTION_BLOCK = Object.assign({}, FUNCTION_HEADER, {
            starts: {
                end: /\b(end|endfunction)\b/,
                endScope: "keyword",
                keywords: KEYWORDS,
                contains: []
            }
        });
        // parenthesized expression: its "end" is an index (v(end)), not the
        // end of the enclosing block
        var PARENS = {begin: /\(/, end: /\)/, relevance: 0, keywords: KEYWORDS, contains: []};
        PARENS.contains = ["self"].concat(BASE);
        BLOCK.contains = ["self", FUNCTION_BLOCK, PARENS].concat(BASE);
        FUNCTION_BLOCK.starts.contains = [BLOCK, FUNCTION_BLOCK, PARENS].concat(BASE);

        // properties / methods / enumeration [(attributes)] ... end
        var SECTION = {
            begin: /\b(properties|methods|enumeration)\b/,
            beginScope: "keyword",
            end: /\bend\b/,
            endScope: "keyword",
            keywords: KEYWORDS,
            contains: [FUNCTION_BLOCK, BLOCK].concat(BASE)
        };
        var CLASSDEF = {
            begin: /\bclassdef\b/,
            beginScope: "keyword",
            end: /\bend\b/,
            endScope: "keyword",
            keywords: KEYWORDS,
            contains: [SECTION].concat(BASE)
        };

        // ---- top level ----------------------------------------------------

        return {
            name: "Scilab",
            aliases: ["sci"],
            keywords: KEYWORDS,
            illegal: '("|#|/\\*|\\s+/\\w+)',
            contains: [
                CLASSDEF,
                {
                    // "arguments" block of a plain function: keyword at the
                    // start of a line (arguments is never called as a function)
                    className: "keyword",
                    begin: /(?<=^[ \t]*)arguments\b(?=[ \t]*($|\/\/))/,
                    relevance: 0
                },
                FUNCTION_HEADER
            ].concat(BASE)
        };
    }

    hljs.registerLanguage("scilab", scilab);
})();
